<?php require_once __DIR__.'/../includes/functions.php';require_role('parent');$s=$pdo->prepare("SELECT s.admission_number,s.first_name,s.last_name,c.name class_name,d.name division_name FROM students s JOIN parents p ON p.id=s.parent_id JOIN users u ON u.id=p.user_id LEFT JOIN classes c ON c.id=s.class_id LEFT JOIN divisions d ON d.id=s.division_id WHERE u.id=?");$s->execute([$_SESSION['user']['id']]);$rows=$s->fetchAll();$pageTitle='My Children';$base='../';require __DIR__.'/../includes/header.php';?>
<div class="layout"><?php require __DIR__.'/../includes/sidebar.php';?><section class="content"><div class="card"><h1>My Children</h1><div class="table-wrap"><table class="table"><?php if($rows):?><tr><?php foreach(array_keys($rows[0]) as $h):?><th><?=e(ucwords(str_replace('_',' ',$h)))?></th><?php endforeach;?></tr><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e((string)$v)?></td><?php endforeach;?></tr><?php endforeach;?><?php endif;?></table></div></div></section></div><?php require __DIR__.'/../includes/footer.php';?>